import{_ as a,a as i}from"./chunks/image-20261116063402530.DK6B0Klg.js";import{_ as t,o as n,c as o,a2 as r}from"./chunks/framework.CmPiTyN0.js";const g=JSON.parse('{"title":"Interface and Controls","description":"","frontmatter":{"title":"Interface and Controls","outline":"deep"},"headers":[],"relativePath":"en/wiki/interface.md","filePath":"en/wiki/interface.md","lastUpdated":null}'),s={name:"en/wiki/interface.md"};function l(d,e,c,h,p,u){return n(),o("div",null,[...e[0]||(e[0]=[r('<p><a href="./../index.html">← Back to Wiki Home</a></p><h2 id="_10-interface-and-controls" tabindex="-1">10. Interface and Controls <a class="header-anchor" href="#_10-interface-and-controls" aria-label="Permalink to &quot;10. Interface and Controls&quot;">​</a></h2><h3 id="_10-1-man-in-the-loop" tabindex="-1">10.1 Man-in-the-Loop <a class="header-anchor" href="#_10-1-man-in-the-loop" aria-label="Permalink to &quot;10.1 Man-in-the-Loop&quot;">​</a></h3><ul><li>One of RVP&#39;s signature weapon features.</li><li>Two interfaces: TV guidance (HITL_TV) and command-line TV guidance (HITL_CLOS_TV).</li></ul><p><strong>HITL_TV</strong></p><ul><li>After launch, the missile&#39;s TV/thermal video feed opens.</li><li>The operator selects a target point with the crosshair and presses the anchor key (default <code>R</code>) to anchor or re-anchor; the missile tracks that point.</li><li>The HUD shows speed, altitude, distance, flight time, lock state, and operation hints.</li><li>Supports color/black-and-white/thermal switching, mouse-wheel zoom, airburst detonation, and exit.</li></ul><p><img src="'+a+'" alt="image-20261116063514262"></p><p><strong>Figure 10.1 Man-in-the-loop missile.</strong></p><p><strong>HITL_CLOS_TV</strong></p><ul><li>After launch, the same TV/thermal video feed opens.</li><li>The operator directly controls the missile&#39;s control surfaces; a steering cursor is shown at the screen center, with no target anchoring step.</li><li>The HUD shows speed, altitude, distance, flight time, turn rate, and operation hints.</li><li>Also supports video-mode switching, mouse-wheel zoom, airburst detonation, and exit.</li></ul><p><img src="'+i+'" alt="image-20261116063402530"></p><p><strong>Figure 10.2 Man-in-the-loop missile (command-line TV).</strong></p><h3 id="_10-2-hmd" tabindex="-1">10.2 HMD <a class="header-anchor" href="#_10-2-hmd" aria-label="Permalink to &quot;10.2 HMD&quot;">​</a></h3><ul><li>IR-guided missiles support HMD acquisition and off-boresight launch.</li><li>Radar weapon stations support a radar HMD for quickly locking the direction being looked at.</li></ul><h3 id="_10-3-warnings-and-indicators" tabindex="-1">10.3 Warnings and Indicators <a class="header-anchor" href="#_10-3-warnings-and-indicators" aria-label="Permalink to &quot;10.3 Warnings and Indicators&quot;">​</a></h3><ul><li>Laser illumination warning.</li><li>Lock warning and missile-approach warning.</li><li>Support equipment, DIRCM, ECM, APS, and countermeasure status.</li><li>Hit markers, creature damage numbers, and module damage indicators.</li><li>Action cards showing currently available actions and shortcuts.</li></ul><hr>',17)])])}const f=t(s,[["render",l]]);export{g as __pageData,f as default};
